'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>n==null?'—':Number(n).toLocaleString(undefined,{maximumFractionDigits:d});
const initials=n=>n.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const short=n=>n==='UTKAL Cricket Club (UCC).'?'UCC':n==='Kuala Lumpur Cricket Club'?'KLCC':n.split(/\s+/).map(x=>x[0]).slice(0,3).join('').toUpperCase();
const niceDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',matches:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',players:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',teams:'<path d="M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7z"/>',compare:'<path d="M3 17h18M7 17V7m5 10V3m5 14V10"/>',captain:'<path d="M4 21V3m0 1h15l-3 5 3 5H4"/>',coach:'<path d="M4 4h16v12H9l-5 5zM8 8h8m-8 4h4"/>',data:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>'};
const icon=id=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[id]||icons.overview}</svg>`;
const nav=[['overview','The pavilion'],['matches','Match centre'],['players','Players'],['teams','Teams'],['compare','Compare players'],['captain','Captain’s room'],['coach','PlacCric coach'],['data','Data & imports']];
let csrf='',team='',tournament='',tournaments=[],teams=[],page='overview',detail='',seq=0,rosterMode=false,search='',sort='runs',minimum='0',allPlayers=[],comparisonPlayers=[],playerRequest=0;
async function api(url,body){const r=await fetch('/api/'+url,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)});let d=await r.json();if(!r.ok){if(r.status===401&&url!=='login')showLogin();throw Error(d.error||'Request failed')}return d}
const scope=()=>{const q=new URLSearchParams();if(team)q.set('team',team);if(tournament)q.set('tournament',tournament);const s=q.toString();return s?'?'+s:''};
const tscope=(sep='?')=>tournament?sep+'tournament='+encodeURIComponent(tournament):'';
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500)}
function showLogin(){$('#app').hidden=true;$('#login').hidden=false;csrf=''}
async function boot(){const s=await api('session');if(!s.authenticated)return showLogin();csrf=s.csrf;await enter()}
async function enter(){teams=await api('teams');allPlayers=await api('players');await loadTournaments();await loadAiStatus();$('#globalTeam').innerHTML='<option value="">All teams</option>'+teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');$('#login').hidden=true;$('#app').hidden=false;renderRoute()}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;$('#loginError').textContent='';try{const s=await api('login',{pin:$('#pin').value});$('#pin').value='';csrf=s.csrf;await enter()}catch(e){$('#loginError').textContent=e.message}finally{b.disabled=false}};
$('#logout').onclick=async()=>{try{await api('logout',{});showLogin()}catch(e){toast(e.message)}};
$('#globalTeam').onchange=()=>{team=$('#globalTeam').value;renderRoute()};
$('#globalTournament').onchange=()=>{tournament=$('#globalTournament').value;showTournament();renderRoute()};
function go(p,id=''){const target='#'+p+(id?'/'+encodeURIComponent(id):'');if(location.hash===target)renderRoute();else location.hash=target}
window.addEventListener('hashchange',()=>{if(csrf)renderRoute()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-page],[data-player],[data-match],[data-team],[data-roster],[data-ask]');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.dataset.player)go('profile',b.dataset.player);if(b.dataset.match)go('match',b.dataset.match);if(b.dataset.team){team=b.dataset.team;$('#globalTeam').value=team;go('players')}if(b.dataset.roster!==undefined){rosterMode=b.dataset.roster==='true';search='';go('players')}if(b.dataset.ask){$('#question').value=b.dataset.ask;$('#coachForm').requestSubmit()}});
function stat(label,value,note,id){return `<article class="stat-card"><div class="stat-top"><span>${label}</span>${icon(id)}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`}
function leadRows(ps,key,label){return ps.map((p,i)=>`<div class="leader-row"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="avatar">${esc(initials(p.name))}</span><div class="leader-text"><button data-player="${p.id}">${esc(p.name)}</button><small>${esc(p.teams.map(n=>n==='UTKAL Cricket Club (UCC).'?'UCC':n).join(' · '))} · ${p.matches} match${p.matches===1?'':'es'}</small></div><div class="leader-number">${fmt(p[key])}<small>${label}</small></div></div>`).join('')||'<div class="empty">No imported performances for this team yet.</div>'}
function matchCard(m){return `<article class="match-card"><div class="match-meta"><span>${niceDate(m.date)} · ${esc((m.stage||'League match').toUpperCase())}${tournament?'':' · '+esc(m.tournament_name||'')}</span><span class="pill ${m.dls?'amber':''}">${m.dls?'DLS':'COMPLETED'}</span></div>${m.innings.map(i=>`<div class="score-row"><span class="score-team"><span class="team-chip">${esc(short(i.team_name))}</span>${esc(i.team_name)}</span><span class="score-number">${i.runs}/${i.wickets}<small>${i.overs} ov</small></span></div>`).join('')}<p class="result">${esc(m.result)}</p><div class="match-footer"><small class="muted">${esc(m.venue)}</small><button class="quiet" data-match="${m.id}">View scorecard</button></div></article>`}
function barChart(labels,values,colors=false){const max=Math.max(...values,1),w=600,h=210,slot=500/Math.max(values.length,1);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(labels.map((l,i)=>l+': '+values[i]).join(', '))}">${[0,1,2].map(i=>`<line class="gridline" x1="42" y1="${30+i*65}" x2="590" y2="${30+i*65}"/><text x="0" y="${35+i*65}">${Math.round(max*(1-i/2))}</text>`).join('')}${values.map((v,i)=>{const bh=v/max*135,x=60+i*slot;return `<rect ${colors&&i%2?'class="lime"':''} x="${x}" y="${165-bh}" width="${Math.min(slot*.48,70)}" height="${Math.max(bh,2)}" rx="4"/><text class="label" x="${x}" y="${152-bh}">${v}</text><text x="${x}" y="193">${esc(labels[i])}</text>`}).join('')}</svg>`}
const playerTable=ps=>`<div class="table-wrap"><table><thead><tr><th>PLAYER</th><th class="numeric">INN</th><th class="numeric">RUNS</th><th class="numeric">SR</th><th class="numeric">AVG</th><th class="numeric">6s</th><th class="numeric">WKTS</th><th class="numeric">ECO</th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="player-cell"><span class="avatar">${esc(initials(p.name))}</span><div><button data-player="${p.id}">${esc(p.name)}</button><small>${esc(p.teams.join(' · '))}</small></div></div></td>${['innings','runs','strike_rate','average','sixes','wickets','economy'].map(k=>`<td class="numeric">${fmt(p[k],2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!ps.length?'<div class="empty">No players match these filters.</div>':''}`;
async function renderRoute(){const n=++seq;const hash=location.hash.slice(1).split('/');page=hash[0]||'overview';detail=decodeURIComponent(hash[1]||'');const active=page==='profile'?'players':page==='match'?'matches':page==='review'?'data':page;$('#navigation').innerHTML=nav.map(([id,label])=>`<button class="nav-button ${active===id?'active':''}" data-page="${id}">${icon(id)}${label}</button>`).join('');$('#crumb').textContent=nav.find(x=>x[0]===active)?.[1]||'Overview';const descriptions={overview:['THE TOURNAMENT AT A GLANCE','The pavilion','Real scorecards. Clearer cricket.'],matches:['EVERY MATCH, EVERY MOMENT','Match centre','Completed tournament matches with batting and bowling breakdowns.'],players:['THE PEOPLE BEHIND THE NUMBERS','Player explorer','Filter, discover and compare recorded performances.'],teams:['15 CLUBS. ONE COMPETITION.','The clubs','Club listings and actual match participation are shown separately.'],compare:['SIDE BY SIDE','Compare players','A fair comparison starts with the sample size.'],captain:['PREPARE WITH PURPOSE','Captain’s room','Your team against theirs: form, threats, how wickets fall and an optional AI match plan.'],coach:['EVIDENCE BEFORE ADVICE','PlacCric coach','Answers grounded in the scorecards we have imported.'],data:['KNOW WHAT IS COVERED','Data & imports','Upload scorecards, review them, then publish.'],review:['CHECK BEFORE PUBLISHING','Review import','Nothing changes in the statistics until you approve.'],profile:['YOUR GAME, IN FOCUS','Player 360','Tournament-only performance from imported scorecards.'],match:['THE COMPLETE SCORECARD','Match analysis','Batting, bowling and scoring composition.']};const d=descriptions[page]||descriptions.overview;$('#eyebrow').textContent=d[0];$('#pageTitle').textContent=d[1];$('#subtitle').textContent=d[2];$('#content').innerHTML='<div class="loading">Loading scorecards…</div>';try{let html='';
if(page==='overview'){const s=await api('summary'+scope());if(n!==seq)return;const top=s.batting_leaders[0],recent=s.matches[0];html=`<div class="stats">${stat('Teams',team?'1':s.teams.filter(t=>t.played).length,'With imported matches','teams')}${stat('Matches covered',s.completed,'Verified completed scorecards','matches')}${stat('Recorded runs',fmt(s.recorded_runs),team?'Selected team batting totals':'Across both innings','compare')}${stat('Batting players',s.batting_players,'Players with a recorded innings','players')}</div><div class="main-grid"><div><div class="feature"><span class="kicker">BATTING SPOTLIGHT / IMPORTED MATCHES</span>${top?`<div class="feature-layout"><div><h2>${esc(top.name)}</h2><p>${esc(top.teams.join(' · '))}<br>${top.innings} innings · ${fmt(top.strike_rate,2)} strike rate</p><button class="primary" data-player="${top.id}">Explore player</button></div><div class="feature-score">${top.runs}<small>RECORDED RUNS</small></div></div>`:'<h2>No scorecards for this team yet.</h2>'}</div><div class="panel section-gap"><div class="panel-head"><h2>Runs on the board</h2><small>Completed matches · first innings</small></div>${barChart(s.matches.map(m=>niceDate(m.date)),s.matches.map(m=>m.innings[0].runs),true)}<p class="table-note">Match totals, not phase-by-phase scoring. DLS matches are retained and flagged in Match centre.</p></div>${recent?`<div class="section-gap"><div class="panel-head"><h2>Latest result</h2><button class="quiet" data-page="matches">All matches</button></div>${matchCard(recent)}</div>`:''}</div><div><div class="panel"><div class="panel-head"><h2>Run leaders</h2><span class="pill">TOURNAMENT</span></div>${leadRows(s.batting_leaders,'runs','RUNS')}</div><div class="panel section-gap"><div class="panel-head"><h2>Wicket leaders</h2><small>Imported matches</small></div>${leadRows(s.bowling_leaders,'wickets','WICKETS')}</div><div class="panel section-gap"><h2>Your game deserves a closer look.</h2><p class="muted">Open your profile to see the record, the context and a practical training focus.</p><button class="secondary" data-player="32722355">Pritish’s Player 360</button></div></div></div>`;}
else if(page==='matches'){const ms=await api('matches'+scope());if(n!==seq)return;html=`<div class="info">${ms.length} completed match${ms.length===1?'':'es'} imported. Scores come from reviewed imports; this is not a live feed.</div><div class="matches-grid">${ms.map(matchCard).join('')}</div>${!ms.length?'<div class="panel empty">No imported matches for this team. Choose All teams to explore the tournament.</div>':''}`;}
else if(page==='players'){html=`<div class="panel"><div class="tabs"><button class="${!rosterMode?'active':''}" data-roster="false">Match participants</button><button class="${rosterMode?'active':''}" data-roster="true">Club listings</button></div><div class="filters"><label>Search ${rosterMode?'club listing':'player'}<input id="playerSearch" value="${esc(search)}" placeholder="Search by player name…"></label>${!rosterMode?`<label>Sort by<select id="sort">${[['runs','Runs'],['wickets','Wickets'],['strike_rate','Strike rate'],['average','Average'],['economy','Economy'],['name','Name']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Minimum batting innings<select id="minimum"><option value="0">All players</option><option value="1" ${minimum==='1'?'selected':''}>1+ innings</option><option value="2" ${minimum==='2'?'selected':''}>2+ innings</option></select></label>`:''}<button class="secondary" id="clearFilters">Reset</button></div><div id="playerResults"></div><p class="table-note">${rosterMode?'A club listing does not confirm tournament selection. Names alone are not used to merge player identities.':'Player identities use CricHeroes IDs. Average is undefined with no dismissals; a dash means unavailable.'}</p></div>`;}
else if(page==='teams'){const ts=await api('teams'+tscope());if(n!==seq)return;html=`<div class="info">Club listings include historical membership. Match counts below reflect imported completed scorecards${tournament?' for the selected tournament':' across all tournaments'}.</div><div class="team-grid">${ts.filter(t=>!team||t.id==team).map(t=>`<article class="team-card"><div class="team-chip">${esc(short(t.name))}</div><h3>${esc(t.name)}</h3><small class="muted">${t.club_listings} public club listings</small><div class="team-stats"><div><strong>${t.played}</strong><small>MATCHES</small></div><div><strong>${t.wins}</strong><small>WINS</small></div><div><strong>${t.losses}</strong><small>LOSSES</small></div></div><button class="quiet small-gap" data-team="${t.id}">Explore match participants</button></article>`).join('')}</div>`;}
else if(page==='profile'){const p=await api('players/'+(detail||'32722355')+tscope());if(n!==seq)return;html=`<div class="profile-banner"><div class="profile-person"><span class="avatar">${esc(initials(p.name))}</span><div><h2>${esc(p.name)}</h2><small>${esc(p.teams.join(' · '))}</small></div></div><span class="pill">${p.matches} RECORDED MATCH${p.matches===1?'':'ES'}</span></div><div class="stats">${stat('Runs',fmt(p.runs),`${p.innings} batting innings`,'players')}${stat('Strike rate',fmt(p.strike_rate,2),`${p.balls} balls faced`,'compare')}${stat('Average',fmt(p.average,2),`${p.dismissals} dismissals`,'overview')}${stat('Wickets',p.wickets,`${p.overs} overs · ${fmt(p.economy,2)} economy`,'matches')}</div><div class="main-grid"><div class="panel"><div class="panel-head"><h2>Recorded innings</h2><small>Sample size matters</small></div>${barChart(p.batting_history.map(b=>niceDate(b.date)),p.batting_history.map(b=>b.runs))}<div class="table-wrap"><table><thead><tr><th>DATE</th><th class="numeric">R</th><th class="numeric">B</th><th class="numeric">4s</th><th class="numeric">6s</th></tr></thead><tbody>${p.batting_history.map(b=>`<tr><td><button class="quiet" data-match="${b.match_id}">${niceDate(b.date)}</button><span class="dismissal">${esc(b.dismissal)}</span></td><td class="numeric"><b>${b.runs}${b.not_out?'*':''}</b></td><td class="numeric">${b.balls}</td><td class="numeric">${b.fours}</td><td class="numeric">${b.sixes}</td></tr>`).join('')}</tbody></table></div><p class="table-note">* Not out. Zero-ball not-out listings are excluded from the innings count.</p></div><div><div class="panel"><div class="panel-head"><h2>Coach’s notebook</h2><span class="pill blue">EVIDENCE</span></div>${p.insights.map(s=>`<p class="insight">${esc(s)}</p>`).join('')}<button class="secondary" data-page="coach">Ask PlacCric coach</button></div><div class="panel section-gap"><h2>Scoring composition</h2><div class="leader-row"><span class="leader-text">Fours</span><strong>${p.fours}</strong></div><div class="leader-row"><span class="leader-text">Sixes</span><strong>${p.sixes}</strong></div><div class="leader-row"><span class="leader-text">Boundary run share</span><strong>${fmt(p.boundary_run_pct,1)}${p.boundary_run_pct==null?'':'%'}</strong></div><p class="muted">Shot zones, batting dot-ball rate and pace/spin matchups need ball-by-ball data.</p></div></div></div>${aiPanel('aiPlayer','AI scouting report','Strengths, weaknesses and how to plan for or against this player, written only from their recorded innings and spells.')}`;}
else if(page==='match'){const m=await api('matches/'+detail);if(n!==seq)return;html=`<button class="quiet back" data-page="matches">Back to matches</button>${matchCard(m)}${m.warning?`<div class="warning">${esc(m.warning)}</div>`:''}<div class="info">${esc(m.toss)}${m.pom?' · Player of the match: '+esc(m.pom):''} · ${esc(m.tournament_name)}${m.source_url?` · <a href="${esc(m.source_url)}" target="_blank" rel="noopener">Verify source scorecard</a>`:' · Imported from a scorecard file'}</div>${m.innings.map(i=>`<section class="panel section-gap"><div class="panel-head"><h2>${esc(i.team_name)}</h2><span class="comparison-title">${i.runs}/${i.wickets} <small class="muted">${i.overs} ov</small></span></div><div class="table-wrap"><table><thead><tr><th>BATTER</th><th class="numeric">R</th><th class="numeric">B</th><th class="numeric">4s</th><th class="numeric">6s</th><th class="numeric">SR</th></tr></thead><tbody>${i.batting.map(b=>`<tr><td><button class="quiet" data-player="${b.player_id}">${esc(b.name)}</button><span class="dismissal">${esc(b.dismissal)}</span></td><td class="numeric"><b>${b.runs}${b.not_out?'*':''}</b></td><td class="numeric">${b.balls}</td><td class="numeric">${b.fours}</td><td class="numeric">${b.sixes}</td><td class="numeric">${fmt(b.strike_rate,2)}</td></tr>`).join('')}<tr><td>Extras</td><td class="numeric"><b>${i.extras}</b></td><td colspan="4"></td></tr></tbody></table></div><h3 class="section-gap">Bowling</h3><div class="table-wrap"><table><thead><tr><th>BOWLER</th><th class="numeric">O</th><th class="numeric">R</th><th class="numeric">W</th><th class="numeric">DOTS</th><th class="numeric">WD</th><th class="numeric">NB</th><th class="numeric">ECO</th></tr></thead><tbody>${i.bowling.map(b=>`<tr><td><button class="quiet" data-player="${b.player_id}">${esc(b.name)}</button></td>${[b.overs,b.runs,b.wickets,b.dots,b.wides,b.no_balls,fmt(b.economy,2)].map(v=>`<td class="numeric">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`).join('')}<section class="panel section-gap" aria-labelledby="revHead"><div class="panel-head"><h2 id="revHead">Revision history</h2><small>Every published version is kept</small></div><div id="revisions"><div class="loading">Loading revisions…</div></div></section>`;}
else if(page==='compare'){const ps=await api('players'+scope());if(n!==seq)return;comparisonPlayers=ps;html=`<div class="panel"><div class="filters"><label>Player A<select id="compareA">${options(ps)}</select></label><label>Player B<select id="compareB">${options(ps)}</select></label></div><div id="compareResults"></div></div><div class="info">Both players use the same imported tournament scope. Players with no dismissals have no finite batting average.</div>${aiPanel('aiCompare','AI comparison','Which situations suit each player, using only both players’ recorded innings and spells. It will not crown a winner on a small sample.')}`;}
else if(page==='captain'){html=await renderCaptain();if(n!==seq)return}
else if(page==='coach'){html=`<div class="main-grid"><div class="panel"><div class="panel-head"><h2>Talk about your cricket</h2><span class="pill blue">SCORECARD EVIDENCE</span></div><div class="filters"><label>Player<select id="coachPlayer">${options(allPlayers)}</select></label></div><div class="conversation" id="conversation"><div class="message"><b>PLACCRIC</b>Choose a player and ask about recorded batting, bowling or a practice focus. I’ll explain the figures and where the evidence runs out.</div></div><div class="filters"><button class="secondary" data-ask="How can I improve my batting?">Batting focus</button><button class="secondary" data-ask="Explain my bowling economy">Bowling review</button></div><form id="coachForm" class="chat-form"><input id="question" maxlength="1000" required placeholder="Ask about the recorded performances…" aria-label="Question"><button class="primary">Ask coach</button></form>${aiStatus.configured?`<label class="check"><input type="checkbox" id="coachAi"> Answer with AI (${esc(aiStatus.model)} via OpenRouter); sends this player’s name and recorded statistics</label>`:''}<p class="coach-mode">${aiStatus.configured?'Rules-based answers by default; AI answers are labelled.':'Evidence-based rules · AI not configured · general drills are labelled.'}</p></div><div class="panel"><h2>What PlacCric knows</h2><p class="insight">Batting totals, balls faced, boundaries, dismissals, bowling spells and match results.</p><h3 class="section-gap">What it cannot infer yet</h3><p class="muted">Shot choice, line and length, wagon wheels, pace/spin matchups and phase scoring need ball events or video.</p><button class="quiet" data-page="data">Inspect data coverage</button></div></div>`;}
else if(page==='data'){html=await renderData();if(n!==seq)return}
else if(page==='review'){html=await renderReview(detail);if(n!==seq)return}
if(n!==seq)return;$('#content').innerHTML=html;wirePage();}catch(e){if(n!==seq)return;$('#content').innerHTML=`<div class="panel empty">${esc(e.message)}<br><button class="quiet" id="retry">Try again</button></div>`;$('#retry').onclick=renderRoute}}
function options(ps){return ps.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}
async function loadPlayers(){const request=++playerRequest;const q=new URLSearchParams({q:search,sort,min:minimum});if(team)q.set('team',team);if(tournament&&!rosterMode)q.set('tournament',tournament);const mode=rosterMode;try{const ps=await api((mode?'rosters':'players')+'?'+q);if(page!=='players'||mode!==rosterMode||request!==playerRequest)return;$('#playerResults').innerHTML=mode?`<div class="table-wrap"><table><thead><tr><th>CLUB LISTING</th><th>TEAM</th><th>STATUS</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.team_name)}</td><td><span class="pill blue">CLUB LISTING</span></td></tr>`).join('')}</tbody></table></div>${!ps.length?'<div class="empty">No matching listings.</div>':''}`:playerTable(ps)}catch(e){toast(e.message)}}
function wirePage(){if(page==='players'){loadPlayers();let timer;$('#playerSearch').oninput=e=>{search=e.target.value;clearTimeout(timer);timer=setTimeout(loadPlayers,180)};if(!rosterMode){$('#sort').onchange=e=>{sort=e.target.value;loadPlayers()};$('#minimum').onchange=e=>{minimum=e.target.value;loadPlayers()}}$('#clearFilters').onclick=()=>{search='';sort='runs';minimum='0';renderRoute()}}
if(page==='compare'){const ps=comparisonPlayers;const update=()=>{const a=ps.find(p=>p.id==$('#compareA').value),b=ps.find(p=>p.id==$('#compareB').value);if(!a||!b){$('#compareResults').innerHTML='<div class="empty">No imported players in this team.</div>';return}const fields=[['Matches','matches'],['Batting innings','innings'],['Runs','runs'],['Balls faced','balls'],['Strike rate','strike_rate'],['Average','average'],['Highest score','high_score'],['Fours','fours'],['Sixes','sixes'],['Wickets','wickets'],['Bowling economy','economy']];$('#compareResults').innerHTML=`<div class="table-wrap"><table><thead><tr><th>METRIC</th><th class="numeric">${esc(a.name)}</th><th class="numeric">${esc(b.name)}</th></tr></thead><tbody>${fields.map(([l,k])=>`<tr><td>${l}</td><td class="numeric">${fmt(a[k],2)}</td><td class="numeric">${fmt(b[k],2)}</td></tr>`).join('')}</tbody></table></div><p class="table-note">${a.name===b.name?'You selected the same player on both sides.':'Small samples describe these matches; they do not establish overall ability.'}</p>`};if(ps.length>1)$('#compareB').selectedIndex=1;$('#compareA').onchange=update;$('#compareB').onchange=update;update();if($('#aiCompareRun'))$('#aiCompareRun').onclick=()=>{if($('#compareA').value===$('#compareB').value){$('#aiCompareOut').innerHTML='<p class="error">Choose two different players.</p>';return}runAi('aiCompare',{kind:'compare',player_ids:[$('#compareA').value,$('#compareB').value],tournament:tournament||null})}}
if(page==='profile'&&$('#aiPlayerRun'))$('#aiPlayerRun').onclick=()=>runAi('aiPlayer',{kind:'player',player_id:detail||'32722355',tournament:tournament||null});
if(page==='captain')wireCaptain();
if(page==='coach'){$('#coachPlayer').value='32722355';$('#coachForm').onsubmit=async e=>{e.preventDefault();const q=$('#question').value;if(!q.trim())return;const b=e.submitter;if(b)b.disabled=true;try{const useAi=$('#coachAi')&&$('#coachAi').checked;let reply;if(useAi){const d=await api('ai/analyze',{kind:'player',player_id:$('#coachPlayer').value,question:q,tournament:tournament||null});reply=`<b>PLACCRIC AI · ${esc(d.model)}</b><div class="ai-answer">${mdLite(d.answer)}</div><small class="muted">AI-generated from imported scorecards${d.cached?' (saved answer)':''}; check before relying on it.</small>`;loadAiStatus()}else{const d=await api('coach',{player_id:$('#coachPlayer').value,question:q});reply=`<b>PLACCRIC</b>${esc(d.answer)}`}$('#conversation').insertAdjacentHTML('beforeend',`<div class="message user"><b>YOU</b>${esc(q)}</div><div class="message">${reply}</div>`);$('#question').value='';$('#conversation').scrollTop=$('#conversation').scrollHeight}catch(e){toast(e.message)}finally{if(b)b.disabled=false}}}
if(page==='data')wireData();if(page==='review')wireReview();if(page==='match')wireMatch()}
async function loadTournaments(){tournaments=await api('tournaments');const sel=$('#globalTournament');sel.innerHTML='<option value="">All tournaments</option>'+tournaments.map(t=>`<option value="${t.id}">${esc(tourLabel(t))}</option>`).join('');if(tournament&&!tournaments.some(t=>String(t.id)===String(tournament)))tournament='';sel.value=tournament;showTournament()}
function showTournament(){const t=tournaments.find(t=>String(t.id)===String(tournament));$('#tourName').textContent=t?t.name:'All tournaments';$('#tourMeta').textContent=t?`${t.kind==='friendly'?'Friendlies':'T'+t.overs_per_innings} · ${t.matches} match${t.matches===1?'':'es'} imported`:`${tournaments.length} tournament${tournaments.length===1?'':'s'}`}
const statusPill=s=>`<span class="pill ${{staged:'amber',rejected:'red',new:'blue',correction:'amber'}[s]||''}">${esc(String(s).toUpperCase())}</span>`
const when=d=>d?new Date(d).toLocaleString():'—'
const plural=(n,w)=>`${n} ${w}${n===1?'':(w.endsWith('ch')?'es':'s')}`
async function renderData(){const [d,batches]=await Promise.all([api('data'),api('imports')]);const tourOptions=tournaments.map(t=>`<option value="${t.id}" ${String(t.id)===String(tournament)?'selected':''}>${esc(tourLabel(t))}</option>`).join('')
return `<p class="data-intro">${plural(d.coverage.completed_scorecards,'completed match')} imported across ${plural(d.coverage.tournaments.length,'tournament')}. Statistics change only when you approve a reviewed upload; PlacCric never fetches data from CricHeroes by itself.</p><div class="main-grid"><div class="panel"><div class="panel-head"><h2>Coverage</h2><span class="pill">IMPORTED DATA</span></div><div class="status-list">${d.coverage.tournaments.map(t=>`<div class="status-line"><span>${esc(t.name)}<br><small class="muted">${t.kind==='friendly'?'One-off matches between any teams':`T${t.overs_per_innings} · max ${t.max_overs_per_bowler} overs per bowler`}${t.last_match?' · latest '+niceDate(t.last_match):''}</small></span><strong>${plural(t.matches,'match')}</strong></div>`).join('')||'<div class="empty">No tournaments yet. Run the seed command or add one below.</div>'}${[['Ball-by-ball','Not imported'],['Automatic sync','None — uploads only'],['Database','PostgreSQL'],['Login','Server-verified PIN (interim)']].map(([k,v])=>`<div class="status-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p class="table-note">Club listings do not establish tournament squads. Source corrections may change results.</p><details class="section-gap"><summary>Add a tournament</summary><form id="tournamentForm" class="mini-form small-gap"><label>Name<input name="name" required minlength="3" maxlength="200" placeholder="Active CC T20 Season 5"></label><label>CricHeroes tournament ID (optional: the number in the tournament link)<input name="external_id" inputmode="numeric" pattern="[0-9]*" maxlength="20"></label><label>Link name (optional, e.g. active-cc-t20-season-5; used to check scorecard links)<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="200"></label><div class="filters"><label>Overs per innings<input name="overs_per_innings" type="number" min="1" max="50" required value="20"></label><label>Max overs per bowler<input name="max_overs_per_bowler" type="number" min="1" max="50" required value="4"></label></div><button class="secondary" type="submit">Add tournament</button><span id="tournamentStatus" class="error" role="status"></span></form></details></div><div class="panel"><h2>Upload a scorecard</h2><p class="muted">A CricHeroes “Download Scorecard” PDF (up to 10 MB) or scorecard JSON (up to 2 MB). The file is checked and shown for review first; statistics change only after you approve.</p><form id="importForm" class="mini-form"><label for="importFile">Scorecard file</label><input id="importFile" type="file" accept=".pdf,application/pdf,.json,application/json" required><label for="importTournament">Tournament</label><select id="importTournament" required><option value="">Choose…</option>${tourOptions}</select><small class="muted">Not listed? Open <a href="#data" id="openAddTournament">Add a tournament</a> in Coverage. For one-off games choose “Friendly Match”.</small><label for="importMatch">CricHeroes match ID (PDF only; filled in from Scorecard_&lt;id&gt;.pdf)</label><input id="importMatch" inputmode="numeric" pattern="[0-9]*" maxlength="20" placeholder="27466505"><label for="importUrl">Scorecard link (PDF only, optional)</label><input id="importUrl" type="url" maxlength="1000" placeholder="https://cricheroes.com/scorecard/…"><button class="primary" type="submit">Upload &amp; review</button><span id="importStatus" class="error" role="status"></span></form><p class="table-note">Uploaded files are kept privately on the server for audit and are never published.</p></div></div><div class="panel section-gap"><h2>Uploads</h2>${batches.length?`<div class="table-wrap"><table><thead><tr><th>#</th><th>UPLOADED</th><th>FILE</th><th>TOURNAMENT</th><th>MATCH</th><th>STATUS</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${batches.map(b=>`<tr><td>${b.id}</td><td class="nowrap">${esc(when(b.created_at))}</td><td>${esc(b.original_filename)}</td><td>${esc(b.tournament_name)}</td><td>${esc(b.match_ids.join(', '))}</td><td>${statusPill(b.status)}</td><td><a class="quiet" href="#review/${b.id}">${b.status==='staged'?'Review':'View'}</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No uploads yet.</div>'}</div><div class="panel section-gap"><h2>Source caveats</h2>${d.warnings.map(w=>`<div class="warning">${esc(w.warning)}${w.source_url?` <a href="${esc(w.source_url)}" target="_blank" rel="noopener">Source</a>`:''}</div>`).join('')||'<p class="muted">No caveats recorded.</p>'}</div>`}
function wireData(){const add=$('#openAddTournament');if(add)add.onclick=e=>{e.preventDefault();const d=document.querySelector('details');d.open=true;d.scrollIntoView({behavior:'smooth',block:'center'});d.querySelector('input').focus()};const file=$('#importFile');file.onchange=()=>{const f=file.files[0],m=f&&f.name.match(/(\d{6,20})/);if(m&&!$('#importMatch').value)$('#importMatch').value=m[1]}
$('#importForm').onsubmit=async e=>{e.preventDefault();const f=file.files[0],b=e.target.querySelector('button[type=submit]'),st=$('#importStatus');st.textContent='';if(!f)return;const pdf=/\.pdf$/i.test(f.name)||f.type==='application/pdf',json=/\.json$/i.test(f.name)||f.type==='application/json';if(!pdf&&!json){st.textContent='Choose a PDF or JSON file.';return}const limit=pdf?10_000_000:2_000_000;if(f.size>limit){st.textContent=`${pdf?'PDF':'JSON'} files must be at most ${limit/1e6} MB.`;return}if(!$('#importTournament').value){st.textContent='Choose the tournament this scorecard belongs to.';$('#importTournament').focus();return}b.disabled=true;$('#importStatus').className='muted';st.textContent='Uploading and checking…';try{const q=new URLSearchParams({tournament:$('#importTournament').value});if(pdf){if($('#importMatch').value.trim())q.set('match_id',$('#importMatch').value.trim());if($('#importUrl').value.trim())q.set('source_url',$('#importUrl').value.trim())}const r=await fetch('/api/imports?'+q,{method:'POST',headers:{'Content-Type':pdf?'application/pdf':'application/json','X-CSRF-Token':csrf,'X-Filename':encodeURIComponent(f.name)},body:f});const d=await r.json();if(!r.ok){if(r.status===401)showLogin();throw Error(d.error||'Upload failed')}if(d.already_uploaded)toast('This file was uploaded before; showing that upload.');go('review',d.batch_id)}catch(err){$('#importStatus').className='error';st.textContent=err.message;b.disabled=false}}
$('#tournamentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button[type=submit]'),st=$('#tournamentStatus');b.disabled=true;st.textContent='';try{await api('tournaments',{name:f.get('name').trim(),external_id:f.get('external_id').trim(),slug:f.get('slug').trim(),overs_per_innings:Number(f.get('overs_per_innings')),max_overs_per_bowler:Number(f.get('max_overs_per_bowler'))});await loadTournaments();toast('Tournament added');renderRoute()}catch(err){st.textContent=err.message;b.disabled=false}}}
let reviewData=null
function identityControl(i){const label=`Who is ${i.name} (${i.team})?`;return `<select data-key="${esc(i.key)}" aria-label="${esc(label)}">${i.requires_choice?'<option value="">Choose…</option>':''}<option value="new" ${i.requires_choice?'':'selected'}>New player</option>${i.suggestions.map(s=>`<option value="link:${esc(s.id)}">Same as ${esc(s.name)} (${Math.round(s.score*100)}% similar${s.same_team?'':', other team'})</option>`).join('')}</select><input class="small-gap" data-cid="${esc(i.key)}" aria-label="${esc('CricHeroes player ID for '+i.name+' (optional)')}" placeholder="CricHeroes player ID (optional)" inputmode="numeric" pattern="[0-9]*" maxlength="20">`}
function reviewMatch(m,staged){const open=m.identities.filter(i=>i.status==='unresolved');return `<section class="panel section-gap"><div class="panel-head"><h2>Match ${esc(m.id||'?')}${m.stage?' · '+esc(m.stage):''}</h2>${staged?statusPill(m.status):''}</div><p>${esc(m.team1)} vs ${esc(m.team2)} · ${m.date?niceDate(m.date):'no date'} · ${esc(m.venue)}<br><strong>${esc(m.result)}</strong>${m.toss?' · '+esc(m.toss):''}${m.source_url?` · <a href="${esc(m.source_url)}" target="_blank" rel="noopener">Source</a>`:''}</p><div class="table-wrap"><table><thead><tr><th>INNINGS</th><th class="numeric">SCORE</th><th class="numeric">OVERS</th><th class="numeric">EXTRAS</th><th class="numeric">BATTERS</th><th class="numeric">BOWLERS</th></tr></thead><tbody>${m.innings.map(i=>`<tr><td>${esc(i.team)}</td><td class="numeric">${i.runs}/${i.wickets}</td><td class="numeric">${i.overs}</td><td class="numeric">${i.extras}</td><td class="numeric">${i.batters}</td><td class="numeric">${i.bowlers}</td></tr>`).join('')}</tbody></table></div>${staged&&m.status==='unchanged'?'<p class="info">Identical to the published scorecard; approving changes nothing.</p>':''}${staged&&m.changes.length?`<h3 class="section-gap">Changes to the published match</h3><div class="table-wrap"><table><thead><tr><th>FIELD</th><th>NOW</th><th>AFTER APPROVAL</th></tr></thead><tbody>${m.changes.map(c=>`<tr><td>${esc(c.field)}</td><td>${esc(c.old)}</td><td>${esc(c.new)}</td></tr>`).join('')}</tbody></table></div>`:''}${staged&&m.identities.length?`<h3 class="section-gap">Players: ${m.identities.length-open.length} recognised, ${open.length} to confirm</h3><p class="muted">PDFs contain names, not CricHeroes IDs. Names you confirm are remembered for that team. Similar names are only suggestions; nothing is merged unless you choose it.</p><div class="table-wrap"><table class="identity-table"><thead><tr><th>NAME IN FILE</th><th>TEAM</th><th>PLAYER</th></tr></thead><tbody>${m.identities.map(i=>`<tr><td>${esc(i.name)}<br><small class="muted">${esc(i.roles.join(', '))}</small></td><td>${esc(i.team)}</td><td>${i.status==='confirmed'?`✓ ${esc(i.player.name)} <small class="muted">confirmed earlier</small>`:identityControl(i)}</td></tr>`).join('')}</tbody></table></div>`:''}</section>`}
async function renderReview(id){const p=await api('imports/'+encodeURIComponent(id));reviewData=p;const src=p.source||{};const facts=[['Source',p.kind==='pdf'?'CricHeroes scorecard PDF'+(src.title?' — '+src.title:''):'Scorecard JSON'],['Tournament',`${p.tournament.name} (T${p.rules.overs_per_innings}, max ${p.rules.max_overs_per_bowler} overs per bowler)`],['Uploaded',`${when(p.created_at)} by ${p.created_by}`],...(src.printed_at?[['PDF generated',src.printed_at]]:[]),['File SHA-256',p.file_sha256.slice(0,16)+'…'],...(p.reviewed_at?[[p.status==='approved'?'Approved':'Rejected',`${when(p.reviewed_at)} by ${p.reviewed_by}`]]:[])]
return `<a class="quiet back" href="#data">Back to uploads</a><div class="panel"><div class="panel-head"><h2>${esc(p.filename)}</h2>${statusPill(p.status)}</div><div class="status-list">${facts.map(([k,v])=>`<div class="status-line"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div></div>${p.errors.length?`<div class="panel section-gap error-panel" role="alert"><h2>Errors: fix the source before approving</h2><ul>${p.errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:''}${p.warnings.length?`<div class="warning"><strong>Please check:</strong><ul>${p.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}${p.matches.map(m=>reviewMatch(m,p.status==='staged')).join('')}${p.outcome?`<div class="info">Result: ${p.outcome.map(o=>`match ${esc(o.match_id)} ${o.result==='published'?'published as revision '+o.revision:'unchanged'}`).join('; ')}. <button class="quiet" data-match="${esc(p.outcome[0].match_id)}">View match</button></div>`:''}${p.status==='staged'?`<div class="panel section-gap"><h2>Publish</h2><p class="muted">Approving publishes ${p.matches.length===1?'this match':'these matches'} in one step and records a revision you can restore later. Rejecting leaves statistics unchanged.</p><div class="filters"><button class="primary" id="approveImport" ${p.approvable?'':'disabled aria-describedby="approveHelp"'}>Approve &amp; publish</button><button class="secondary" id="rejectImport">Reject</button></div>${p.approvable?'':'<p id="approveHelp" class="error">Approval is unavailable until the errors above are fixed in the source.</p>'}<p id="reviewStatus" class="error" role="alert"></p></div>`:''}`}
function wireReview(){if(!$('#approveImport'))return;const selects=[...document.querySelectorAll('select[data-key]')];const cidFor=k=>document.querySelector(`input[data-cid="${CSS.escape(k)}"]`);const sync=()=>selects.forEach(s=>{const c=cidFor(s.dataset.key);if(c)c.hidden=s.value!=='new'});selects.forEach(s=>s.onchange=sync);sync()
$('#approveImport').onclick=async e=>{const b=e.currentTarget,st=$('#reviewStatus');st.textContent='';const decisions={};const missing=selects.find(s=>!s.value);if(missing){st.textContent='Choose who each name marked “Choose…” is before approving.';missing.focus();return}selects.forEach(s=>{const k=s.dataset.key;decisions[k]=s.value==='new'?{action:'new',cricheroes_id:(cidFor(k)?.value||'').trim()}:{action:'link',player_id:s.value.slice(5)}});b.disabled=true;try{const d=await api('imports/'+reviewData.id+'/approve',{decisions});allPlayers=await api('players');await loadTournaments();toast(d.outcome.map(o=>o.result==='published'?`Match ${o.match_id} published`:`Match ${o.match_id} unchanged`).join('; '));renderRoute()}catch(err){st.textContent=err.message;b.disabled=false}}
$('#rejectImport').onclick=async()=>{if(!confirm('Reject this upload? Statistics will not change.'))return;try{await api('imports/'+reviewData.id+'/reject',{});toast('Upload rejected');renderRoute()}catch(err){$('#reviewStatus').textContent=err.message}}}
async function wireMatch(){const box=$('#revisions'),id=detail;if(!box)return;try{const rs=await api('matches/'+encodeURIComponent(id)+'/revisions');if(page!=='match'||detail!==id)return;box.innerHTML=rs.length?`<div class="table-wrap"><table><thead><tr><th>REVISION</th><th>PUBLISHED</th><th>BY</th><th>NOTE</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.number}${r.current?' <span class="pill">CURRENT</span>':''}</td><td class="nowrap">${esc(when(r.created_at))}</td><td>${esc(r.created_by)}</td><td>${esc(r.note)}${r.batch_id?` · <a href="#review/${r.batch_id}">upload #${r.batch_id}</a>`:''}</td><td>${r.current?'':`<button class="quiet" data-restore="${r.number}">Restore</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No revisions recorded for this match.</p>';box.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{if(!confirm(`Restore revision ${b.dataset.restore}? It is published as a new revision; nothing is deleted.`))return;b.disabled=true;try{const d=await api('matches/'+encodeURIComponent(id)+'/restore',{revision:Number(b.dataset.restore)});toast(d.unchanged?'That revision is already current':'Restored as revision '+d.revision);renderRoute()}catch(err){toast(err.message);b.disabled=false}})}catch(err){box.innerHTML=`<p class="error">${esc(err.message)}</p>`}}
let aiStatus={configured:false,missing:['OPENROUTER_API_KEY','OPENROUTER_MODEL']}
async function loadAiStatus(){try{aiStatus=await api('ai/status')}catch(e){aiStatus={configured:false,missing:[]}}}
function mdLite(src){const out=[];let list=false;const inline=s=>esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');for(const raw of String(src).split('\n')){const l=raw.trim();const li=l.match(/^[-*]\s+(.*)$/);if(li){if(!list){out.push('<ul>');list=true}out.push(`<li>${inline(li[1])}</li>`);continue}if(list){out.push('</ul>');list=false}if(!l)continue;const h=l.match(/^#{1,4}\s+(.*)$/);out.push(h?`<h3>${inline(h[1])}</h3>`:`<p>${inline(l)}</p>`)}if(list)out.push('</ul>');return out.join('')}
function aiPanel(id,title,lead,controls=''){if(!aiStatus.configured)return `<section class="panel section-gap ai-panel" aria-labelledby="${id}Head"><div class="panel-head"><h2 id="${id}Head">${title}</h2><span class="pill">AI · OFF</span></div><p class="muted">AI analysis is optional and currently switched off. To enable it, add ${aiStatus.missing.map(m=>`<code>${m}</code>`).join(' and ')||'the OpenRouter settings'} to <code>.env</code> and restart (see docs/AI.md). Everything else on this page works without it.</p></section>`
return `<section class="panel section-gap ai-panel" aria-labelledby="${id}Head"><div class="panel-head"><h2 id="${id}Head">${title}</h2><span class="pill blue">AI · ${esc(aiStatus.model)}</span></div><p class="muted">${lead}</p>${controls}<div class="filters"><button class="primary" type="button" id="${id}Run">Generate</button></div><p class="ai-disclosure">Sends team and player names with the statistics PlacCric computed from your imported scorecards to OpenRouter (${esc(aiStatus.model)}). No IDs, PIN or uploaded files. ${aiStatus.used_today}/${aiStatus.daily_limit} AI requests used today; repeats of the same question are free.</p><div id="${id}Out" class="ai-output" aria-live="polite"></div></section>`}
async function runAi(id,body){const out=$('#'+id+'Out'),btn=$('#'+id+'Run');if(!out||!btn)return;btn.disabled=true;out.innerHTML='<div class="loading">Analysing… this can take up to a minute.</div>';try{const d=await api('ai/analyze',body);out.innerHTML=`<div class="ai-answer">${mdLite(d.answer)}</div><p class="ai-meta">AI-generated by ${esc(d.model)}${d.cached?' · saved answer (no new request)':''} · ${esc(when(d.created_at))}${d.prompt_tokens!=null?` · ${d.prompt_tokens}+${d.completion_tokens} tokens`:''}. Check it against the figures above before acting on it.</p><button class="quiet" type="button" data-refresh="${id}">Ask again (new request)</button>`;out.querySelector('[data-refresh]').onclick=()=>runAi(id,{...body,refresh:true});await loadAiStatus()}catch(e){out.innerHTML=`<p class="error">${esc(e.message)}</p>`}finally{btn.disabled=false}}
const tourLabel=t=>t.kind==='friendly'?`${t.name} (friendlies)`:t.name
const pct=(n,total)=>total?Math.round(n*100/total):0
function bars(title,counts){const total=Object.values(counts||{}).reduce((a,b)=>a+b,0);return `<div class="bar-block"><h3>${esc(title)}</h3>${total?Object.entries(counts).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><span class="bar-track" aria-hidden="true"><span class="bar-fill" data-pct="${pct(v,total)}"></span></span><strong>${v}<small> (${pct(v,total)}%)</small></strong></div>`).join(''):'<p class="muted">No dismissals recorded.</p>'}</div>`}
function formChips(f){return f.length?f.map(r=>`<span class="form-chip ${r==='W'?'win':'loss'}" aria-label="${r==='W'?'won':'lost'}">${r}</span>`).join(''):'—'}
function playerList(title,rows,kind){return `<div class="panel"><h3>${esc(title)}</h3>${rows.length?`<div class="table-wrap"><table><thead><tr><th>PLAYER</th>${kind==='bat'?'<th class="numeric">INN</th><th class="numeric">RUNS</th><th class="numeric">SR</th><th class="numeric">AVG</th>':'<th class="numeric">OVERS</th><th class="numeric">WKTS</th><th class="numeric">ECO</th><th class="numeric">DOT %</th>'}</tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name)}</td>${kind==='bat'?`<td class="numeric">${p.innings}</td><td class="numeric"><b>${p.runs}</b></td><td class="numeric">${fmt(p.strike_rate,1)}</td><td class="numeric">${fmt(p.average,1)}</td>`:`<td class="numeric">${p.overs}</td><td class="numeric"><b>${p.wickets}</b></td><td class="numeric">${fmt(p.economy,2)}</td><td class="numeric">${fmt(p.dot_ball_pct,1)}</td>`}</tr>`).join('')}</tbody></table></div>`:'<p class="muted">No records in this scope.</p>'}</div>`}
function matchupHtml(r){const a=r.team,b=r.opponent,rec=x=>x.played?`${x.won}/${x.played} won`:'—';const rows=[['Matches imported',a.matches,b.matches],['Won – lost',`${a.won} – ${a.lost}`,`${b.won} – ${b.lost}`],['Batting first',rec(a.batting_first),rec(b.batting_first)],['Chasing',rec(a.chasing),rec(b.chasing)],['Average score',fmt(a.average_score,1),fmt(b.average_score,1)],['Highest / lowest',a.matches?`${a.highest_score} / ${a.lowest_score}`:'—',b.matches?`${b.highest_score} / ${b.lowest_score}`:'—'],['Run rate (batting)',fmt(a.run_rate,2),fmt(b.run_rate,2)],['Wickets lost per match',fmt(a.average_wickets_lost,1),fmt(b.average_wickets_lost,1)],['Runs conceded per over',fmt(a.runs_conceded_per_over,2),fmt(b.runs_conceded_per_over,2)],['Wickets taken per match',fmt(a.average_wickets_taken,1),fmt(b.average_wickets_taken,1)]]
const d=r.dismissals;return `<p class="muted">Scope: ${esc(r.scope)}. Change it with the Tournament filter above.</p><div class="panel"><div class="panel-head"><h2>Team against team</h2>${a.small_sample||b.small_sample?'<span class="pill amber">SMALL SAMPLE</span>':''}</div><div class="table-wrap"><table class="versus-table"><thead><tr><th>METRIC</th><th class="numeric">${esc(a.team)}</th><th class="numeric">${esc(b.team)}</th></tr></thead><tbody>${rows.map(([l,x,y])=>`<tr><td>${l}</td><td class="numeric">${x}</td><td class="numeric">${y}</td></tr>`).join('')}<tr><td>Recent form (oldest → latest)</td><td class="numeric">${formChips(a.recent_form)}</td><td class="numeric">${formChips(b.recent_form)}</td></tr></tbody></table></div></div>
<div class="panel section-gap"><h2>Head to head</h2>${r.head_to_head.length?r.head_to_head.map(m=>`<div class="h2h-row"><div><strong>${esc(m.winner)} won</strong> · ${niceDate(m.date)}${m.stage?' · '+esc(m.stage):''}<br><small class="muted">${esc(m.scores.join(' · '))} · ${esc(m.tournament)}</small></div><button class="quiet" data-match="${esc(m.match_id)}">Scorecard</button></div>`).join(''):'<p class="muted">These teams have not met in the imported matches.</p>'}${d.head_to_head_dismissals.length?`<h3 class="section-gap">Who dismissed whom in these meetings</h3><ul class="plain-list">${d.head_to_head_dismissals.map(x=>`<li><strong>${esc(x.bowler)}</strong> (${esc(x.bowler_team)}) dismissed <strong>${esc(x.batter)}</strong>${x.times>1?` ${x.times} times`:''}</li>`).join('')}</ul>`:''}</div>
<div class="grid-2 section-gap">${playerList(`Their batters — ${b.team}`,r.their_batters,'bat')}${playerList(`Their bowlers — ${b.team}`,r.their_bowlers,'bowl')}${playerList(`Our batters — ${a.team}`,r.our_batters,'bat')}${playerList(`Our bowlers — ${a.team}`,r.our_bowlers,'bowl')}</div>
<div class="panel section-gap"><h2>How wickets fall</h2><div class="grid-2">${bars(`How ${b.team} batters get out`,d.how_batters_get_out[b.team])}${bars(`How ${b.team} bowlers take wickets`,d.how_bowlers_take_wickets[b.team])}${bars(`How ${a.team} batters get out`,d.how_batters_get_out[a.team])}${bars(`How ${a.team} bowlers take wickets`,d.how_bowlers_take_wickets[a.team])}</div><p class="table-note">From the dismissal text of each scorecard. Run outs are not credited to bowlers.</p></div>
<div class="info">${r.data_limits.map(esc).join('<br>')}</div>`}
async function renderCaptain(){const ts=await api('teams'+tscope());const pool=ts.filter(t=>tournament?t.played:(t.played||t.club_listings));const mine=pool.find(t=>team?String(t.id)===String(team):t.name.startsWith('UTKAL'))||pool[0];const opp=pool.find(t=>t.name==='Cyber XI'&&t!==mine)||pool.find(t=>t!==mine);if(pool.length<2)return '<div class="panel empty">At least two teams with imported matches are needed in this scope. Choose another tournament or import more scorecards.</div>'
return `<div class="filters captain-pickers"><label>Your team<select id="captainTeam">${pool.map(t=>`<option value="${t.id}" ${t===mine?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Opposition<select id="opponent">${pool.map(t=>`<option value="${t.id}" ${t===opp?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label></div><div id="captainResults"><div class="loading">Comparing teams…</div></div>${aiPanel('aiMatch','AI match plan','A plan for this fixture written from the comparison above: threats, batting and bowling plans, key match-ups and what the data cannot tell you.',`<label class="block-label">Anything specific? (optional)<textarea id="aiMatchQ" maxlength="1000" rows="2" placeholder="e.g. We are batting first; who should open the bowling?"></textarea></label><label class="check"><input type="checkbox" id="aiMatchNotes"> Include my saved match plan notes</label>`)}<div class="panel section-gap"><div class="panel-head"><h2>Your match plan</h2><small id="notesStatus">Saved in the database</small></div><textarea id="notes" class="note-field" maxlength="10000" placeholder="Opening pair, bowling allocations, field settings and practice priorities…" aria-label="Your match plan"></textarea><button id="saveNotes" class="primary small-gap">Save match plan</button></div>`}
function wireCaptain(){if(!$('#captainTeam'))return;let req=0;const load=async()=>{const n=++req,a=$('#captainTeam').value,b=$('#opponent').value,box=$('#captainResults');if(a===b){box.innerHTML='<div class="panel empty">Choose two different teams.</div>';return}box.innerHTML='<div class="loading">Comparing teams…</div>';try{const r=await api(`captain/matchup?team=${a}&opponent=${b}`+tscope('&'));if(n===req){box.innerHTML=matchupHtml(r);box.querySelectorAll('[data-pct]').forEach(e=>{e.style.width=e.dataset.pct+'%'})}}catch(e){if(n===req)box.innerHTML=`<div class="panel empty">${esc(e.message)}</div>`}};const notes=async()=>{const d=await api('notes?team='+$('#captainTeam').value);$('#notes').value=d.body;$('#notesStatus').textContent=d.updated_at?'Last saved '+new Date(d.updated_at).toLocaleString():'No plan saved yet'};$('#opponent').onchange=load;$('#captainTeam').onchange=()=>{load();notes().catch(e=>toast(e.message))};load();notes().catch(e=>toast(e.message));$('#saveNotes').onclick=async()=>{try{await api('notes',{team:Number($('#captainTeam').value),body:$('#notes').value});$('#notesStatus').textContent='Saved just now';toast('Match plan saved')}catch(e){toast(e.message)}};if($('#aiMatchRun'))$('#aiMatchRun').onclick=()=>runAi('aiMatch',{kind:'matchup',team:Number($('#captainTeam').value),opponent:Number($('#opponent').value),tournament:tournament||null,question:$('#aiMatchQ').value,include_notes:$('#aiMatchNotes').checked})}
boot().catch(e=>{$('#loginError').textContent=e.message;showLogin()});
